#!/bin/sh
# plasma-dialer 6.6.4 (Ubuntu 26.04) + патчи pmOS: 0003 тоны клавиш (libcanberra; 0003-…6.6.4 — первый фрагмент CMakeLists без ringtoneutils.cpp),
# 0004 действие «Open» только у пропущенного вызова (у входящего нет — как в pmOS: только Принять/Отклонить), 0005 выбор SIM (modem-daemon + QML), 0006 свой: тоны следуют настройке клавиатуры Lomiri
# (com.lomiri.keyboard.maliit key-press-feedback), 0007 уведомление о входящем вызове с x-lomiri-snap-decisions (кнопки «Принять/Отклонить»), 0008 ширина листов USSD/IMEI (в 0009 заменена распоркой Item), 0009 значок call-stop-symbolic на красной кнопке, HistoryDelegate pmOS (имя контакта + «SIM N · дата»). -> .deb в out/ (1:6.6.4-0ubuntu1+m52xq4). Звуки dtmf-*.wav — в ../rootfs-files/usr/share/sounds/m52xq/.
# Chroot классик/mesa-build-root2. Лог: build.log. Использование: ./build.sh
set -e
B=$(cd "$(dirname "$0")" && pwd); R=$B/../../mesa-build-root2
sudo cp $B/patches/plasma-dialer-0003-key-tones-canberra.6.6.4.patch $B/patches/plasma-dialer-0004-default-open-action.patch $B/patches/plasma-dialer-0005-m52xq-dual-sim.patch $B/patches/plasma-dialer-0006-key-tones-lomiri-setting.patch $B/patches/plasma-dialer-0007-lomiri-snap-decision.patch $B/patches/plasma-dialer-0008-sheet-width.patch $B/patches/plasma-dialer-0009-ussd-width-icons-history.patch $B/patches/plasma-dialer-0010-m52xq-ussd-buttons-sidebar.patch $B/patches/plasma-dialer-0012-reset-speaker-mute-at-call-end.patch $B/patches/plasma-dialer-0013-add-contact-lomiri.patch $R/build-pd/
sudo chroot $R sh -c 'DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends libcanberra-dev libglib2.0-dev 2>&1 | tail -1'
sudo chroot $R sh -c 'cd /build-pd && rm -rf plasma-dialer-6.6.4 && dpkg-source -x plasma-dialer_6.6.4-0ubuntu1.dsc >/dev/null && cd plasma-dialer-6.6.4 && for f in ../plasma-dialer-0003-key-tones-canberra.6.6.4.patch ../plasma-dialer-0004-default-open-action.patch ../plasma-dialer-0005-m52xq-dual-sim.patch ../plasma-dialer-0006-key-tones-lomiri-setting.patch ../plasma-dialer-0007-lomiri-snap-decision.patch ../plasma-dialer-0008-sheet-width.patch ../plasma-dialer-0009-ussd-width-icons-history.patch ../plasma-dialer-0010-m52xq-ussd-buttons-sidebar.patch ../plasma-dialer-0012-reset-speaker-mute-at-call-end.patch ../plasma-dialer-0013-add-contact-lomiri.patch; do echo "== $f"; patch -p1 < "$f" || exit 1; done && printf "plasma-dialer (1:6.6.4-0ubuntu1+m52xq4) resolute; urgency=medium\n\n  * m52xq: key tones (libcanberra, follow Lomiri keyboard setting), default notification action, dual SIM selection.\n\n -- m52xq <m52xq@localhost>  Wed, 29 Oct 2026 01:20:00 +0000\n\n" | cat - debian/changelog > /tmp/cl && cp /tmp/cl debian/changelog && DEB_BUILD_OPTIONS="nocheck noautodbgsym" dpkg-buildpackage -b -us -uc -j8 2>&1 | tail -12'
rm -rf $B/out; mkdir -p $B/out; sudo cp $R/build-pd/plasma-dialer_*m52xq4*.deb $B/out/ 2>/dev/null; sudo chown -R $(id -u):$(id -g) $B/out; ls -l $B/out
